contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function runTest(uint256 amount) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 1 wei);
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        c.Collect(amount); if (__ESBMC_reverted()) return;
        uint256 balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        assert(balBefore - balAfter == amount);
    }
}

